def is_toeplitz_matrix(matrix):
    rows = len(matrix)
    cols = len(matrix[0])

    def check_diagonal(start_row, start_col):
        value = matrix[start_row][start_col]
        i, j = start_row, start_col
        while i < rows and j < cols:
            if matrix[i][j] != value:                                       # walk the whole diagonal, comparing every cell to its first value
                return False
            i += 1
            j += 1
        return True

    for start_row in range(rows):                                          # every diagonal starting somewhere in the first column
        if not check_diagonal(start_row, 0):
            return False
    for start_col in range(1, cols):                                       # every diagonal starting somewhere in the first row (excluding the corner, already covered)
        if not check_diagonal(0, start_col):
            return False
    return True


if __name__ == "__main__":
    print(is_toeplitz_matrix([[1, 2, 3, 4], [5, 1, 2, 3], [9, 5, 1, 2]]))

