import java.util.*;

public class Main {
    boolean isToeplitzMatrix(int[][] matrix) {
        int rows = matrix.length, cols = matrix[0].length;
        for (int startRow = 0; startRow < rows; startRow++) {                     // every diagonal starting somewhere in the first column
            if (!checkDiagonal(matrix, startRow, 0, rows, cols)) return false;
        }
        for (int startCol = 1; startCol < cols; startCol++) {                     // every diagonal starting somewhere in the first row (excluding the corner)
            if (!checkDiagonal(matrix, 0, startCol, rows, cols)) return false;
        }
        return true;
    }

    boolean checkDiagonal(int[][] matrix, int startRow, int startCol, int rows, int cols) {
        int value = matrix[startRow][startCol];
        int i = startRow, j = startCol;
        while (i < rows && j < cols) {
            if (matrix[i][j] != value) return false;                                // walk the whole diagonal, comparing every cell to its first value
            i++;
            j++;
        }
        return true;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.isToeplitzMatrix(new int[][]{{1, 2, 3, 4}, {5, 1, 2, 3}, {9, 5, 1, 2}}));
    }
}

